CREATE DATABASE IF NOT EXISTS educhat CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE educhat;
SET FOREIGN_KEY_CHECKS=0;
DROP TABLE IF EXISTS app_downloads,student_activity_events,student_emblems,student_points,quiz_answers,quiz_attempts,quiz_questions,quizzes,chat_messages,chat_sessions,lesson_progress,student_progress,subscriptions,subscription_plans,parent_student_links,student_parent_codes,parents,lessons,units,subjects,media,admins,users,referral_promoters,grades,settings;
SET FOREIGN_KEY_CHECKS=1;
CREATE TABLE grades(id INT AUTO_INCREMENT PRIMARY KEY,grade_number TINYINT NOT NULL UNIQUE,name VARCHAR(50) NOT NULL,status ENUM('active','inactive') DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE referral_promoters(id INT AUTO_INCREMENT PRIMARY KEY,full_name VARCHAR(100) NOT NULL,email VARCHAR(190) NULL UNIQUE,phone VARCHAR(15) NULL UNIQUE,referral_code VARCHAR(24) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,status ENUM('active','inactive') NOT NULL DEFAULT 'active',last_login_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE users(id INT AUTO_INCREMENT PRIMARY KEY,full_name VARCHAR(100) NOT NULL,username VARCHAR(30) NOT NULL UNIQUE,email VARCHAR(190) NULL UNIQUE,phone VARCHAR(15) NULL UNIQUE,phone_verified_at DATETIME NULL,school_name VARCHAR(190) NULL,district VARCHAR(80) NULL,password_hash VARCHAR(255) NOT NULL,grade_id INT NOT NULL,medium ENUM('Sinhala','Tamil','English') NOT NULL,preferred_language ENUM('en','si','ta') NOT NULL DEFAULT 'en',profile_image VARCHAR(255),subscription_expires_at DATETIME NULL,referral_promoter_id INT NULL,referral_code_used VARCHAR(24) NULL,status ENUM('active','inactive') DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX(grade_id),INDEX(school_name),INDEX users_referral_promoter_idx(referral_promoter_id),FOREIGN KEY(grade_id) REFERENCES grades(id),CONSTRAINT users_referral_promoter_fk FOREIGN KEY(referral_promoter_id) REFERENCES referral_promoters(id) ON DELETE RESTRICT);
CREATE TABLE admins(id INT AUTO_INCREMENT PRIMARY KEY,full_name VARCHAR(100) NOT NULL,username VARCHAR(50) NOT NULL UNIQUE,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role ENUM('admin','super_admin') DEFAULT 'admin',status ENUM('active','inactive') DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE parents(id INT AUTO_INCREMENT PRIMARY KEY,full_name VARCHAR(100) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,status ENUM('active','inactive') DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE student_parent_codes(student_id INT PRIMARY KEY,link_code CHAR(8) NOT NULL UNIQUE,expires_at DATETIME NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(student_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE parent_student_links(parent_id INT NOT NULL,student_id INT NOT NULL,linked_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,last_seen_at DATETIME NULL,PRIMARY KEY(parent_id,student_id),INDEX(student_id),FOREIGN KEY(parent_id) REFERENCES parents(id) ON DELETE CASCADE,FOREIGN KEY(student_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE media(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(30) UNIQUE NOT NULL,label_en VARCHAR(30),label_si VARCHAR(30),label_ta VARCHAR(30),status ENUM('active','inactive') DEFAULT 'active');
CREATE TABLE subjects(id INT AUTO_INCREMENT PRIMARY KEY,grade_id INT NOT NULL,subject_code VARCHAR(30) NOT NULL,name_en VARCHAR(100) NOT NULL,name_si VARCHAR(100) NOT NULL,name_ta VARCHAR(100) NOT NULL,description_en TEXT,description_si TEXT,description_ta TEXT,icon VARCHAR(20) DEFAULT '📘',status ENUM('active','inactive') DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE(grade_id,subject_code),FOREIGN KEY(grade_id) REFERENCES grades(id));
CREATE TABLE units(id INT AUTO_INCREMENT PRIMARY KEY,grade_id INT NOT NULL,subject_id INT NOT NULL,unit_number INT NOT NULL,name_en VARCHAR(180),name_si VARCHAR(180),name_ta VARCHAR(180),description_en TEXT,description_si TEXT,description_ta TEXT,display_order INT DEFAULT 0,status ENUM('active','inactive') DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE(subject_id,unit_number),INDEX(grade_id),FOREIGN KEY(grade_id) REFERENCES grades(id),FOREIGN KEY(subject_id) REFERENCES subjects(id) ON DELETE CASCADE);
CREATE TABLE lessons(id INT AUTO_INCREMENT PRIMARY KEY,grade_id INT NOT NULL,medium ENUM('All','Sinhala','Tamil','English') DEFAULT 'All',content_source VARCHAR(30) NOT NULL DEFAULT 'manual',subject_id INT NOT NULL,unit_id INT NOT NULL,title_en VARCHAR(200),title_si VARCHAR(200),title_ta VARCHAR(200),short_description_en TEXT,short_description_si TEXT,short_description_ta TEXT,content_en MEDIUMTEXT,content_si MEDIUMTEXT,content_ta MEDIUMTEXT,learning_objectives_en TEXT,learning_objectives_si TEXT,learning_objectives_ta TEXT,key_terms_en TEXT,key_terms_si TEXT,key_terms_ta TEXT,examples_en TEXT,examples_si TEXT,examples_ta TEXT,summary_en TEXT,summary_si TEXT,summary_ta TEXT,display_order INT DEFAULT 0,status ENUM('active','inactive') DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX(grade_id,subject_id,unit_id),FULLTEXT(title_en,summary_en,key_terms_en),FOREIGN KEY(grade_id) REFERENCES grades(id),FOREIGN KEY(subject_id) REFERENCES subjects(id),FOREIGN KEY(unit_id) REFERENCES units(id));
CREATE TABLE lesson_source_pdfs(lesson_id INT PRIMARY KEY,local_file VARCHAR(500) NOT NULL,start_page INT NOT NULL DEFAULT 1,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(lesson_id) REFERENCES lessons(id) ON DELETE CASCADE);
CREATE TABLE lesson_progress(id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,lesson_id INT NOT NULL,opened_at DATETIME NOT NULL,last_opened_at DATETIME NOT NULL,completed_at DATETIME NULL,UNIQUE(user_id,lesson_id),INDEX(last_opened_at),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(lesson_id) REFERENCES lessons(id) ON DELETE CASCADE);
CREATE TABLE quizzes(id INT AUTO_INCREMENT PRIMARY KEY,grade_id INT NOT NULL,subject_id INT NOT NULL,unit_id INT NULL,lesson_id INT NULL,title_en VARCHAR(200),title_si VARCHAR(200),title_ta VARCHAR(200),timer_minutes INT NULL,pass_mark INT DEFAULT 50,status ENUM('active','inactive') DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(grade_id) REFERENCES grades(id),FOREIGN KEY(subject_id) REFERENCES subjects(id),FOREIGN KEY(unit_id) REFERENCES units(id) ON DELETE SET NULL,FOREIGN KEY(lesson_id) REFERENCES lessons(id) ON DELETE SET NULL);
CREATE TABLE quiz_questions(id INT AUTO_INCREMENT PRIMARY KEY,quiz_id INT NOT NULL,activity_type ENUM('lesson_quiz','challenge','missing','matching') NOT NULL DEFAULT 'lesson_quiz',question_en TEXT,question_si TEXT,question_ta TEXT,option_a_en TEXT,option_a_si TEXT,option_a_ta TEXT,option_b_en TEXT,option_b_si TEXT,option_b_ta TEXT,option_c_en TEXT,option_c_si TEXT,option_c_ta TEXT,option_d_en TEXT,option_d_si TEXT,option_d_ta TEXT,correct_option ENUM('a','b','c','d') NOT NULL,explanation_en TEXT,explanation_si TEXT,explanation_ta TEXT,display_order INT DEFAULT 0,status ENUM('active','inactive') DEFAULT 'active',FOREIGN KEY(quiz_id) REFERENCES quizzes(id) ON DELETE CASCADE);
CREATE TABLE quiz_attempts(id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,quiz_id INT NOT NULL,score INT NOT NULL,total_questions INT NOT NULL,percentage INT NOT NULL,passed TINYINT(1) NOT NULL,started_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,completed_at DATETIME,INDEX(user_id,completed_at),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(quiz_id) REFERENCES quizzes(id));
CREATE TABLE quiz_answers(id BIGINT AUTO_INCREMENT PRIMARY KEY,attempt_id BIGINT NOT NULL,question_id INT NOT NULL,selected_option ENUM('a','b','c','d') NULL,is_correct TINYINT(1) NOT NULL,UNIQUE(attempt_id,question_id),FOREIGN KEY(attempt_id) REFERENCES quiz_attempts(id) ON DELETE CASCADE,FOREIGN KEY(question_id) REFERENCES quiz_questions(id));
CREATE TABLE chat_sessions(id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,subject_id INT NULL,lesson_id INT NULL,title VARCHAR(200),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,last_activity_at DATETIME,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(subject_id) REFERENCES subjects(id) ON DELETE SET NULL,FOREIGN KEY(lesson_id) REFERENCES lessons(id) ON DELETE SET NULL);
CREATE TABLE chat_messages(id BIGINT AUTO_INCREMENT PRIMARY KEY,session_id BIGINT NOT NULL,user_id INT NOT NULL,role ENUM('user','assistant') NOT NULL,message TEXT NOT NULL,language ENUM('en','si','ta') NOT NULL,subject_id INT NULL,lesson_id INT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(user_id,created_at),FOREIGN KEY(session_id) REFERENCES chat_sessions(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE student_activity_events(id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,event_type ENUM('search','lesson_opened','lesson_completed','quiz_completed') NOT NULL,subject_id INT NULL,lesson_id INT NULL,quiz_id INT NULL,detail VARCHAR(500) NOT NULL,event_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(user_id,event_time),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(subject_id) REFERENCES subjects(id) ON DELETE SET NULL,FOREIGN KEY(lesson_id) REFERENCES lessons(id) ON DELETE SET NULL,FOREIGN KEY(quiz_id) REFERENCES quizzes(id) ON DELETE SET NULL);
CREATE TABLE student_progress(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL UNIQUE,total_completed_lessons INT DEFAULT 0,learning_streak INT DEFAULT 0,last_activity DATE NULL,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE student_points(id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,grade_id INT NOT NULL,subject_id INT NULL,lesson_id INT NULL,quiz_id INT NULL,activity_type VARCHAR(40) NOT NULL,points INT NOT NULL,award_key VARCHAR(190) NOT NULL,description VARCHAR(255) NOT NULL,awarded_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE(user_id,award_key),INDEX(grade_id,user_id),INDEX(user_id,awarded_at),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(grade_id) REFERENCES grades(id),FOREIGN KEY(subject_id) REFERENCES subjects(id),FOREIGN KEY(lesson_id) REFERENCES lessons(id) ON DELETE SET NULL,FOREIGN KEY(quiz_id) REFERENCES quizzes(id) ON DELETE SET NULL);
CREATE TABLE student_emblems(id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,grade_id INT NOT NULL,subject_id INT NOT NULL,lesson_id INT NOT NULL,tier ENUM('bronze','silver','gold','master') NOT NULL,earned_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE(user_id,lesson_id,tier),INDEX(grade_id,user_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(grade_id) REFERENCES grades(id),FOREIGN KEY(subject_id) REFERENCES subjects(id),FOREIGN KEY(lesson_id) REFERENCES lessons(id) ON DELETE CASCADE);
CREATE TABLE subscription_plans(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100),price_lkr DECIMAL(10,2),duration_days INT,features TEXT,status ENUM('active','inactive') DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE subscriptions(id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,plan_id INT NOT NULL,amount_lkr DECIMAL(10,2),base_amount_lkr DECIMAL(10,2) NOT NULL,discount_lkr DECIMAL(10,2) NOT NULL DEFAULT 0,referral_promoter_id INT NULL,payment_method VARCHAR(30),payment_reference VARCHAR(100) UNIQUE,status ENUM('pending','active','rejected','expired') DEFAULT 'pending',starts_at DATETIME NULL,expires_at DATETIME NULL,reviewed_by INT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX subscriptions_referral_promoter_idx(referral_promoter_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(plan_id) REFERENCES subscription_plans(id),FOREIGN KEY(reviewed_by) REFERENCES admins(id) ON DELETE SET NULL,CONSTRAINT subscriptions_referral_promoter_fk FOREIGN KEY(referral_promoter_id) REFERENCES referral_promoters(id) ON DELETE RESTRICT);
CREATE TABLE settings(id INT AUTO_INCREMENT PRIMARY KEY,setting_key VARCHAR(100) UNIQUE,setting_value TEXT,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE curriculum_sources(id INT AUTO_INCREMENT PRIMARY KEY,grade_id INT NOT NULL,subject_name VARCHAR(180) NOT NULL,language ENUM('en','si','ta','mixed') DEFAULT 'mixed',title VARCHAR(255) NOT NULL,source_url TEXT NOT NULL,local_file VARCHAR(255) NOT NULL,file_hash CHAR(64) NOT NULL UNIQUE,status ENUM('active','inactive') DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(grade_id) REFERENCES grades(id));
CREATE TABLE curriculum_chunks(id BIGINT AUTO_INCREMENT PRIMARY KEY,source_id INT NOT NULL,page_number INT NULL,chunk_index INT NOT NULL,content MEDIUMTEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(source_id,page_number),FULLTEXT(content),FOREIGN KEY(source_id) REFERENCES curriculum_sources(id) ON DELETE CASCADE);
CREATE TABLE app_downloads(id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id INT NULL,ip_address VARCHAR(45),user_agent VARCHAR(500),downloaded_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(downloaded_at),INDEX(user_id));
