INSERT INTO subjects(grade_id,subject_code,name_en,name_si,name_ta,description_en,description_si,description_ta,icon) VALUES
(1,'MATH','Mathematics','ගණිතය','கணிதம்','Numbers, shapes and measurement.','සංඛ්‍යා, හැඩ සහ මිනුම්.','எண்கள், வடிவங்கள் மற்றும் அளவீடு.','➗'),(1,'SCI','Science','විද්‍යාව','அறிவியல்','Living things, matter, energy and environment.','ජීවීන්, ද්‍රව්‍ය, ශක්තිය හා පරිසරය.','உயிரினங்கள், பொருள், ஆற்றல் மற்றும் சூழல்.','🔬'),(1,'ENG','English','ඉංග්‍රීසි','ஆங்கிலம்','Language and communication.','භාෂාව හා සන්නිවේදනය.','மொழி மற்றும் தொடர்பாடல்.','🔤'),(1,'SIN','Sinhala','සිංහල','சிங்களம்','Sinhala language learning.','සිංහල භාෂා අධ්‍යයනය.','சிங்கள மொழிக் கற்றல்.','📗'),(1,'TAM','Tamil','දෙමළ','தமிழ்','Tamil language learning.','දෙමළ භාෂා අධ්‍යයනය.','தமிழ் மொழிக் கற்றல்.','📕'),(1,'HIS','History','ඉතිහාසය','வரலாறு','People and the past.','මිනිසුන් හා අතීතය.','மக்களும் கடந்த காலமும்.','🏛️'),(1,'GEO','Geography','භූගෝල විද්‍යාව','புவியியல்','Places, maps and Earth.','ස්ථාන, සිතියම් හා පෘථිවිය.','இடங்கள், வரைபடங்கள் மற்றும் பூமி.','🌍'),(1,'ICT','ICT','තොරතුරු හා සන්නිවේදන තාක්ෂණය','தகவல் தொடர்பாடல் தொழில்நுட்பம்','Computers and safe digital skills.','පරිගණක හා ආරක්ෂිත ඩිජිටල් කුසලතා.','கணினி மற்றும் பாதுகாப்பான டிஜிட்டல் திறன்கள்.','💻'),(1,'HPE','Health and Physical Education','සෞඛ්‍ය හා ශාරීරික අධ්‍යාපනය','சுகாதாரமும் உடற்கல்வியும்','Healthy bodies and active living.','සෞඛ්‍ය සම්පන්න ක්‍රියාශීලී ජීවිතය.','ஆரோக்கியமும் சுறுசுறுப்பான வாழ்வும்.','🏃'),(1,'CIV','Civic Education','පුරවැසි අධ්‍යාපනය','குடியியல் கல்வி','Responsible citizenship.','වගකීම් සහිත පුරවැසිභාවය.','பொறுப்பான குடியுரிமை.','🤝'),(1,'REL','Religion','ආගම','சமயம்','Values and religious learning.','සාරධර්ම හා ආගමික ඉගෙනීම.','விழுமியங்களும் சமயக் கற்றலும்.','🕊️');
INSERT INTO units(grade_id,subject_id,unit_number,name_en,name_si,name_ta,description_en,description_si,description_ta,display_order) VALUES
(1,1,1,'Whole Numbers','පූර්ණ සංඛ්‍යා','முழு எண்கள்','Reading and using whole numbers.','පූර්ණ සංඛ්‍යා කියවීම හා භාවිතය.','முழு எண்களை வாசித்துப் பயன்படுத்தல்.',1),(1,1,2,'Fractions','භාග','பின்னங்கள்','Parts of a whole.','සමස්තයක කොටස්.','ஒரு முழுமையின் பகுதிகள்.',2),(1,1,3,'Basic Geometry','මූලික ජ්‍යාමිතිය','அடிப்படை வடிவியல்','Lines, angles and shapes.','රේඛා, කෝණ හා හැඩ.','கோடுகள், கோணங்கள் மற்றும் வடிவங்கள்.',3),(1,1,4,'Measurements','මිනුම්','அளவீடுகள்','Length, mass and capacity.','දිග, ස්කන්ධය හා ධාරිතාව.','நீளம், திணிவு மற்றும் கொள்ளளவு.',4),(1,2,1,'Living Things','ජීවී දේ','உயிருள்ளவை','Features and needs of life.','ජීවීන්ගේ ලක්ෂණ හා අවශ්‍යතා.','உயிர்களின் பண்புகளும் தேவைகளும்.',1),(1,2,2,'Matter','ද්‍රව්‍ය','பொருள்','Solids, liquids and gases.','ඝන, ද්‍රව හා වායු.','திண்மம், திரவம் மற்றும் வாயு.',2),(1,2,3,'Energy','ශක්තිය','ஆற்றல்','Forms and uses of energy.','ශක්ති ආකාර හා භාවිත.','ஆற்றலின் வடிவங்களும் பயன்களும்.',3),(1,2,4,'Environment','පරිසරය','சுற்றுச்சூழல்','Caring for ecosystems.','පරිසර පද්ධති රැකබලා ගැනීම.','சூழலமைப்புகளைப் பாதுகாத்தல்.',4),(1,8,1,'Introduction to Computers','පරිගණක හැඳින්වීම','கணினி அறிமுகம்','What computers do.','පරිගණක කරන දේ.','கணினிகள் செய்யும் பணிகள்.',1),(1,8,2,'Computer Components','පරිගණක කොටස්','கணினி கூறுகள்','Hardware components.','දෘඪාංග කොටස්.','வன்பொருள் கூறுகள்.',2),(1,8,3,'Safe Computer Use','ආරක්ෂිත පරිගණක භාවිතය','பாதுகாப்பான கணினிப் பயன்பாடு','Safety and wellbeing.','ආරක්ෂාව හා යහපැවැත්ම.','பாதுகாப்பும் நலனும்.',3),(1,8,4,'Basic Digital Skills','මූලික ඩිජිටල් කුසලතා','அடிப்படை டிஜிட்டல் திறன்கள்','Files, typing and applications.','ගොනු, ටයිප් කිරීම හා යෙදුම්.','கோப்புகள், தட்டச்சு மற்றும் செயலிகள்.',4);
INSERT INTO lessons(grade_id,medium,subject_id,unit_id,title_en,title_si,title_ta,short_description_en,short_description_si,short_description_ta,content_en,content_si,content_ta,learning_objectives_en,learning_objectives_si,learning_objectives_ta,key_terms_en,key_terms_si,key_terms_ta,examples_en,examples_si,examples_ta,summary_en,summary_si,summary_ta,display_order) SELECT 1,'All',subject_id,id,name_en,name_si,name_ta,description_en,description_si,description_ta,CONCAT(name_en,' helps us understand ',description_en,' This is short demonstration content.'),CONCAT(name_si,' මගින් ',description_si,' තේරුම් ගනිමු. මෙය කෙටි නියැදි අන්තර්ගතයකි.'),CONCAT(name_ta,' மூலம் ',description_ta,' புரிந்துகொள்வோம். இது சுருக்கமான மாதிரி உள்ளடக்கம்.'),CONCAT('Identify and explain ',LOWER(name_en),'.'),CONCAT(name_si,' හඳුනාගෙන පැහැදිලි කිරීම.'),CONCAT(name_ta,' அடையாளம் கண்டு விளக்குதல்.'),name_en,name_si,name_ta,CONCAT('Think of one everyday example of ',LOWER(name_en),'.'),CONCAT(name_si,' සඳහා දෛනික උදාහරණයක් සිතන්න.'),CONCAT(name_ta,' குறித்த நாளாந்த உதாரணம் ஒன்றை நினைக்கவும்.'),CONCAT(name_en,' is an important Grade 6 idea.'),CONCAT(name_si,' 6 ශ්‍රේණියේ වැදගත් අදහසකි.'),CONCAT(name_ta,' தரம் 6 இன் முக்கிய கருத்தாகும்.'),1 FROM units;
INSERT INTO quizzes(grade_id,subject_id,unit_id,lesson_id,title_en,title_si,title_ta,timer_minutes,pass_mark) VALUES(1,1,1,1,'Grade 6 Mathematics Sample Quiz','6 ශ්‍රේණිය ගණිත නියැදි ප්‍රශ්නාවලිය','தரம் 6 கணித மாதிரி வினாடி வினா',10,60),(1,2,5,5,'Grade 6 Science Sample Quiz','6 ශ්‍රේණිය විද්‍යා නියැදි ප්‍රශ්නාවලිය','தரம் 6 அறிவியல் மாதிரி வினாடி வினா',10,60),(1,8,9,9,'Grade 6 ICT Sample Quiz','6 ශ්‍රේණිය ICT නියැදි ප්‍රශ්නාවලිය','தரம் 6 ICT மாதிரி வினாடி வினா',10,60);
INSERT INTO quiz_questions(quiz_id,question_en,question_si,question_ta,option_a_en,option_a_si,option_a_ta,option_b_en,option_b_si,option_b_ta,option_c_en,option_c_si,option_c_ta,option_d_en,option_d_si,option_d_ta,correct_option,explanation_en,explanation_si,explanation_ta,display_order) VALUES
(1,'What is 25 + 17?','25 + 17 කීයද?','25 + 17 எவ்வளவு?','42','42','42','32','32','32','52','52','52','41','41','41','a','Add ones, then tens.','එකස්ථාන හා දසස්ථාන එකතු කරන්න.','ஒன்றுகள், பத்துகளை கூட்டுக.',1),(1,'Half of 10 is?','10 හි අඩක්?','10 இன் பாதி?','2','2','2','5','5','5','10','10','10','20','20','20','b','10 divided by 2 is 5.','10 දෙකෙන් බෙදූ විට 5යි.','10 ஐ 2 ஆல் வகுத்தால் 5.',2),(1,'A triangle has how many sides?','ත්‍රිකෝණයක පැති කීයද?','முக்கோணத்திற்கு எத்தனை பக்கங்கள்?','2','2','2','3','3','3','4','4','4','5','5','5','b','A triangle has three sides.','ත්‍රිකෝණයට පැති තුනකි.','முக்கோணத்திற்கு மூன்று பக்கங்கள்.',3),(1,'100 cm equals?','100 cm සමාන වන්නේ?','100 cm என்பது?','1 m','1 m','1 m','10 m','10 m','10 m','1 km','1 km','1 km','10 cm','10 cm','10 cm','a','100 centimetres make one metre.','සෙන්ටිමීටර 100ක් මීටරයකි.','100 செ.மீ ஒரு மீட்டர்.',4),(1,'Which is largest?','විශාලතම සංඛ්‍යාව කුමක්ද?','பெரிய எண் எது?','9','9','9','19','19','19','91','91','91','29','29','29','c','91 has nine tens.','91 හි දහයේ ඒවා නවයකි.','91 இல் ஒன்பது பத்துகள் உள்ளன.',5),
(2,'Which is living?','ජීවී දෙය කුමක්ද?','உயிருள்ளது எது?','Rock','ගල','கல்','Plant','ශාකය','தாவரம்','Water','ජලය','நீர்','Air','වාතය','காற்று','b','Plants grow and reproduce.','ශාක වර්ධනය වී ප්‍රජනනය කරයි.','தாவரங்கள் வளர்ந்து இனப்பெருக்கம் செய்கின்றன.',1),(2,'Ice is a?','අයිස් යනු?','பனி என்பது?','Solid','ඝනයක්','திண்மம்','Liquid','ද්‍රවයක්','திரவம்','Gas','වායුවක්','வாயு','Light','ආලෝකය','ஒளி','a','Ice has a fixed shape.','අයිස්ට නියත හැඩයක් ඇත.','பனிக்கு நிலையான வடிவம் உண்டு.',2),(2,'The Sun gives us?','සූර්යයා අපට ලබා දෙන්නේ?','சூரியன் தருவது?','Sound only','ශබ්දය පමණි','ஒலி மட்டும்','Light and heat','ආලෝකය හා තාපය','ஒளியும் வெப்பமும்','Water','ජලය','நீர்','Soil','පස','மண்','b','The Sun provides light and heat energy.','සූර්යයා ආලෝක හා තාප ශක්තිය ලබා දෙයි.','சூரியன் ஒளி மற்றும் வெப்ப ஆற்றலை தருகிறது.',3),(2,'Which action protects nature?','පරිසරය රකින්නේ කුමක්ද?','இயற்கையைப் பாதுகாப்பது எது?','Littering','කසළ දැමීම','குப்பை போடுதல்','Planting trees','ගස් සිටුවීම','மரம் நடுதல்','Wasting water','ජලය නාස්ති කිරීම','நீரை வீணாக்குதல்','Burning plastic','ප්ලාස්ටික් පිළිස්සීම','பிளாஸ்டிக் எரித்தல்','b','Trees support habitats.','ගස් වාසස්ථාන සඳහා උපකාරී වේ.','மரங்கள் வாழிடங்களுக்கு உதவுகின்றன.',4),(2,'Water at room temperature is usually?','කාමර උෂ්ණත්වයේ ජලය සාමාන්‍යයෙන්?','அறை வெப்பநிலையில் நீர்?','Solid','ඝන','திண்மம்','Liquid','ද්‍රව','திரவம்','Gas','වායු','வாயு','Energy','ශක්තිය','ஆற்றல்','b','Water flows as a liquid.','ජලය ද්‍රවයක් ලෙස ගලා යයි.','நீர் திரவமாக ஓடுகிறது.',5),
(3,'Which device shows output?','ප්‍රතිදානය පෙන්වන්නේ කුමක්ද?','வெளியீட்டைக் காட்டுவது எது?','Keyboard','යතුරුපුවරුව','விசைப்பலகை','Monitor','මොනිටරය','திரை','Mouse','මූසිකය','சுட்டி','Microphone','මයික්‍රොෆෝනය','ஒலிவாங்கி','b','A monitor displays visual output.','මොනිටරය දෘශ්‍ය ප්‍රතිදානය පෙන්වයි.','திரை காட்சி வெளியீட்டைக் காட்டும்.',1),(3,'Which is an input device?','ආදාන උපාංගයක් කුමක්ද?','உள்ளீட்டு சாதனம் எது?','Printer','මුද්‍රකය','அச்சுப்பொறி','Speaker','ස්පීකරය','ஒலிபெருக்கி','Keyboard','යතුරුපුවරුව','விசைப்பலகை','Monitor','මොනිටරය','திரை','c','A keyboard sends typed input.','යතුරුපුවරුව ටයිප් කළ ආදානය යවයි.','விசைப்பலகை தட்டச்சு உள்ளீட்டை அனுப்பும்.',2),(3,'A strong password should be?','ශක්තිමත් මුරපදයක් විය යුත්තේ?','வலுவான கடவுச்சொல் எப்படி?','Easy to guess','අනුමාන කිරීමට පහසු','ஊகிக்க எளிதானது','Shared publicly','ප්‍රසිද්ධියේ බෙදාගත්','பகிரங்கமாக பகிர்ந்தது','Long and unique','දිගු හා සුවිශේෂී','நீளமானதும் தனித்துவமானதும்','Your name','ඔබේ නම','உங்கள் பெயர்','c','Long unique passwords are safer.','දිගු සුවිශේෂී මුරපද වඩා ආරක්ෂිතය.','நீளமான தனித்துவமான கடவுச்சொற்கள் பாதுகாப்பானவை.',3),(3,'What stores a file?','ගොනුවක් ගබඩා කරන්නේ කුමක්ද?','கோப்பைச் சேமிப்பது எது?','Storage device','ගබඩා උපාංගය','சேமிப்புச் சாதனம்','Chair','පුටුව','நாற்காலி','Desk','මේසය','மேசை','Cable only','කේබලයක් පමණි','கம்பி மட்டும்','a','Storage keeps digital files.','ගබඩාව ඩිජිටල් ගොනු තබා ගනී.','சேமிப்பு டிஜிட்டல் கோப்புகளை வைத்திருக்கும்.',4),(3,'For safe use, take regular?','ආරක්ෂිත භාවිතයට නිතර ගත යුත්තේ?','பாதுகாப்பான பயன்பாட்டிற்கு எடுக்க வேண்டியது?','Breaks','විවේක','இடைவேளைகள்','Passwords from friends','මිතුරන්ගේ මුරපද','நண்பர்களின் கடவுச்சொற்கள்','Unknown downloads','නොදන්නා බාගැනීම්','தெரியாத பதிவிறக்கங்கள்','Personal data requests','පුද්ගලික දත්ත ඉල්ලීම්','தனிப்பட்ட தரவு கோரல்கள்','a','Breaks protect eyes and posture.','විවේක ඇස් හා ඉරියව් රකියි.','இடைவேளைகள் கண்களையும் உடல்நிலையையும் பாதுகாக்கும்.',5);
